<script module lang="ts">
/**
 * Markdown.Body: the parsed reply and its caret.
 *
 * Generated by `pnpm shells` from `packages/shells/src/members/markdown.ts`, the member's
 * framework-neutral description. Never edit it by hand: change the description and
 * run `pnpm shells`.
 */

import {
  joinSlot,
  markdownEndsInProse,
  markdownShallowestHeading,
  parseMarkdown,
} from '@polymorph/svelte'
import styles from '@polymorph/recipes/ai/markdown.module.css'
import MarkdownBlocks from './MarkdownBlocks.svelte'
import Text from '../structure/Text.svelte'
import type { CitationSource } from './SourceList.svelte'

export interface MarkdownBodyProps {
  /**
   * The markdown received so far.
   */
  source: string
  size: 'sm' | 'md'
  sources: CitationSource[]
  streaming: boolean
}
</script>

<script lang="ts">
let { source, size, sources, streaming }: MarkdownBodyProps = $props()
const joined = joinSlot(undefined, () => ({ size: size }))
const blocks = $derived(parseMarkdown(source, { citations: sources.length }))
const shallowest = $derived(markdownShallowestHeading(blocks))
</script>

{@render joined.start?.()
}{#if joined.shown
  }<MarkdownBlocks {blocks} {size} {sources} {shallowest} caret={streaming}
  />{#if streaming && !markdownEndsInProse(blocks)
    }<Text {size}><span class={styles.caret} aria-hidden="true"></span></Text
  >{/if
}{/if
}{@render joined.end?.()}
